from __future__ import annotations
from dataclasses import dataclass
from math import sqrt

@dataclass(frozen=True)
class Profile:
    quotient: int
    code: int
    kl: float
    samples: int

    @property
    def effective(self) -> float:
        return self.quotient + self.code + self.kl

def evaluate(profile: Profile, structural: int, posterior: float, epsilon: float) -> dict[str, float | bool]:
    valid_components = profile.quotient + profile.code <= structural and profile.kl <= posterior
    total = structural + posterior
    return {"components_valid": valid_components, "total_budget": total,
            "sample_budget": profile.samples * epsilon**2,
            "radius": sqrt(profile.effective / profile.samples),
            "certified": valid_components and total <= profile.samples * epsilon**2}

if __name__ == "__main__":
    print(evaluate(Profile(120, 180, 4.0, 10_000), 300, 4.0, 0.2))

from __future__ import annotations
from math import ceil, sqrt

def architecture_report(widths: list[int], active: int, posterior: float, epsilon: float, samples: int) -> dict[str, float | int]:
    structural = active + sum(widths)
    total = structural + posterior
    return {"structural_complexity": structural, "total_budget": total,
            "minimum_samples": ceil(total / epsilon**2 - 1e-12),
            "radius": sqrt(total / samples)}

if __name__ == "__main__":
    print(architecture_report([100, 50, 10], 240, 90.0, 0.35, 4_000))

from __future__ import annotations
from math import sqrt

def enlargement_table(base_dimension: int, added: list[int], complexity: float, samples: int) -> list[tuple[int, float]]:
    radius = sqrt(complexity / samples)
    return [(base_dimension + amount, radius) for amount in added]

if __name__ == "__main__":
    for dimension, radius in enlargement_table(750, [0, 1_000, 1_000_000], 1.0, 1_000):
        print(f"dimension={dimension:9d}, radius={radius:.6f}")

