from __future__ import annotations
from math import ceil, sqrt

def architecture_budget(widths: list[int], active: int, posterior: float, epsilon: float, samples: int) -> tuple[int, float, int, float]:
    if epsilon <= 0 or samples <= 0:
        raise ValueError("epsilon and samples must be positive")
    structural = active + sum(widths)
    total = structural + posterior
    return structural, total, ceil(total / epsilon**2 - 1e-12), sqrt(total / samples)

from __future__ import annotations
from math import sqrt

def rank_certificates(complexities: list[float], samples: int) -> list[tuple[float, float]]:
    if samples <= 0 or any(value < 0 for value in complexities):
        raise ValueError("invalid statistical domain")
    return [(value, sqrt(value / samples)) for value in sorted(complexities)]

